// Consolidate all read rows from Google Sheets into a single array
const items = $input.all();
const boardsFromSheet = [];

for (const item of items) {
  const row = item.json || {};
  if (row.BoardName || row.board_name || row.BoardID || row.board_id) {
    boardsFromSheet.push(row);
  }
}

return [{
  json: {
    boardsFromSheet: boardsFromSheet,
    fetchedBoardsCount: boardsFromSheet.length,
    timestamp: new Date().toISOString()
  }
}];

// PARSE & VALIDATE GEMINI DATA WITH PILLAR-AWARE FALLBACKS
