const prev = $('Pick Next Finmatrix Keyword, Angle & Board').item.json || {};
const kw = (prev.targetKeyword || 'Financial Calculator').toLowerCase();
const pillar = (prev.pillar || '').toLowerCase();
const intent = prev.intentType || 'CALCULATOR';

